bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
docker inspect "$cid" --format 'running={{.State.Running}} restart={{.RestartCount}} image={{.Image}} started={{.State.StartedAt}}'
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
test "$(docker ps --filter label=com.docker.compose.project=gace-createvdobot --filter label=com.docker.compose.service=videobot-poll -q | wc -l)" -eq 1 || exit 62
docker logs --since 30m "$cid" 2>&1 | tail -n 100 | sed -E 's/[0-9]{6,}:[A-Za-z0-9_-]{20,}/[REDACTED]/g' > /tmp/createvdobot-menu-diagnostic.log
docker exec -i -w /opt/videobot "$cid" node --input-type=module - <<'JS'
import {readFileSync} from 'node:fs';
import {menuPage} from './src/telegram/menuPanel.mjs';
const panel=menuPage('home');
console.log('MENU_KEYS',JSON.stringify(panel.reply_markup.inline_keyboard.map(r=>r.map(b=>({text:b.text,data:b.callback_data??null})))));
const token=readFileSync('/run/secrets/videobot_telegram_token','utf8').trim();
const root=process.env.VIDEOBOT_BOT_API_BASE_URL||process.env.TELEGRAM_BOT_API_BASE_URL||'https://api.telegram.org';
const base=/^https:\/\/api.telegram.org$|^http:\/\/telegram-bot-api:8081$/.test(root)?root:'https://api.telegram.org';
for(const method of ['getMe','getWebhookInfo']){
 const r=await fetch(base+'/bot'+token+'/'+method,{signal:AbortSignal.timeout(10000)});
 const j=await r.json();console.log(method,JSON.stringify({ok:j.ok,code:j.error_code,bot:j.result?.username,webhook:!!j.result?.url,pending:j.result?.pending_update_count}));
}
JS
docker logs "$cid" 2>&1 | grep -Fq 'CREATOR_DM_POLL_READY=PASS' || exit 63
echo MENU_RUNTIME_STATIC_READY
python3 - <<'PY'
from pathlib import Path
import re
s=Path('/tmp/createvdobot-menu-diagnostic.log').read_text()
for key in ['409','429','401','403','error','ERROR','FAIL','ECONNREFUSED','timeout','STALE','QUARANTINE','poll','callback']:
 print(key, len(re.findall(re.escape(key),s,re.I)))
for line in s.splitlines():
 if re.search(r'ERROR|FAIL|409|429|QUARANTINE|exception',line,re.I):
  print(re.sub(r'\b[0-9]{6,}\b','[ID]',line)[:300])
PY
